#include <zephyr/kernel.h>
#include <zephyr/sys/cobs.h>
#include <zephyr/sys/util.h>

size_t cobs_encode(uint8_t *dst, size_t dst_len, const uint8_t *src, size_t src_len)
{
    size_t encoded_len = 0;
    const uint8_t *end = src + src_len;
    uint8_t *code_ptr = dst;
    uint8_t code = 1;

    if (dst_len == 0) {
        return 0;
    }

    dst++; /* Reserve space for the first code byte */
    encoded_len++;

    while (src < end) {
        if (encoded_len >= dst_len) {
            return 0; /* Not enough space in destination buffer */
        }

        if (*src == 0x00) {
            *code_ptr = code;
            code_ptr = dst;
            code = 1;
            dst++;
            encoded_len++;
        } else {
            *dst++ = *src;
            code++;
            encoded_len++;
            if (code == 0xFF) {
                *code_ptr = code;
                code_ptr = dst;
                code = 1;
                dst++;
                encoded_len++;
            }
        }
        src++;
    }

    *code_ptr = code;

    if (encoded_len >= dst_len) {
        return 0; /* Not enough space for the final delimiter */
    }

    *dst = 0x00; /* Add the final delimiter */
    encoded_len++;

    return encoded_len;
}

size_t cobs_decode(uint8_t *dst, size_t dst_len, const uint8_t *src, size_t src_len)
{
    size_t decoded_len = 0;
    uint8_t code;
    const uint8_t *end = src + src_len;

    while (src < end) {
        code = *src++;

        if (code == 0x00) {
            /* Invalid COBS data: 0x00 byte in the middle of the frame */
            return 0;
        }

        if (decoded_len + code - 1 > dst_len) {
            /* Not enough space in destination buffer */
            return 0;
        }

        for (int i = 1; i < code; i++) {
            if (src >= end) {
                /* Invalid COBS data: not enough source data */
                return 0;
            }
            *dst++ = *src++;
            decoded_len++;
        }

        /* Insert 0x00 byte unless it's the last block and the original
         * data didn't end with 0x00. The COBS encoder adds a final 0x00
         * if the original data does not end with 0x00. If the original
         * data ends with 0x00, the encoder encodes it as part of the data,
         * and the 'code' byte will be 1. So, if code is 1, we insert 0x00.
         * If code > 1, we insert 0x00. The only case we don't insert 0x00
         * is if we are at the end of the encoded buffer and the last 'code'
         * byte was not 1. This means the original data did not end with 0x00,
         * and the final 0x00 is the frame delimiter.
         */
        if (code < 0xFF && src < end) {
            *dst++ = 0x00;
            decoded_len++;
        }
    }

    return decoded_len;
}

void cobs_decode_ctx_init(struct cobs_decode_ctx *ctx)
{
    ctx->code = 0x00;
    ctx->dst_ptr = NULL;
    ctx->dst_len = 0;
    ctx->decoded_len = 0;
    ctx->insert_zero = false;
}

int cobs_decode_stream(struct cobs_decode_ctx *ctx, uint8_t *dst, size_t dst_len,
                       const uint8_t *src, size_t src_len, size_t *decoded_len_out)
{
    if (ctx->dst_ptr == NULL) {
        ctx->dst_ptr = dst;
        ctx->dst_len = dst_len;
        ctx->decoded_len = 0;
        ctx->insert_zero = false;
    }

    for (size_t i = 0; i < src_len; i++) {
        uint8_t byte = src[i];

        if (ctx->code == 0x00) { /* Expecting a code byte */
            if (ctx->insert_zero) {
                if (ctx->decoded_len >= ctx->dst_len) {
                    return -ENOMEM;
                }
                *ctx->dst_ptr++ = 0x00;
                ctx->decoded_len++;
                ctx->insert_zero = false;
            }

            if (byte == 0x00) { /* Frame delimiter */
                *decoded_len_out = ctx->decoded_len;
                cobs_decode_ctx_init(ctx);
                return 1;
            }
            ctx->code = byte;
        } else { /* Expecting data byte */
            if (ctx->decoded_len >= ctx->dst_len) {
                return -ENOMEM;
            }
            *ctx->dst_ptr++ = byte;
            ctx->decoded_len++;
            ctx->code--;

            if (ctx->code == 0x00) { /* Block finished, prepare to insert 0x00 */
                ctx->insert_zero = true;
            }
        }
    }

    *decoded_len_out = ctx->decoded_len; /* Update decoded_len_out for partial frame */
    return 0;
}
